with valid_inventory as (select * from inventory where (last_restock > '2023-05-01' and store_id in (2, 3, 4, 5)) or product_id in (1, 5, 10)), inventory_stats as (select date_format(last_restock, 'yyyy-MM') as last_restock_month, min(quantity) as min_quantity from valid_inventory group by date_format(last_restock, 'yyyy-MM')) select last_restock_month, min_quantity from inventory_stats where min_quantity >= 160 order by min_quantity;
